// METHOD 1 — X-Frame-Options header (older, widely supported)
// DENY: page cannot be embedded anywhere
// SAMEORIGIN: page can only be embedded by pages on the same origin
// ALLOW-FROM https://trusted.com: only this origin can embed (deprecated)

app.use((req, res, next) => {
  res.setHeader('X-Frame-Options', 'DENY');
  // or
  res.setHeader('X-Frame-Options', 'SAMEORIGIN');  // for same-origin iframes
  next();
});

// METHOD 2 — CSP frame-ancestors (modern, more flexible, preferred)
// Supersedes X-Frame-Options — set both for backward compatibility

// Deny all iframes:
res.setHeader('Content-Security-Policy', "frame-ancestors 'none'");

// Allow same origin only:
res.setHeader('Content-Security-Policy', "frame-ancestors 'self'");

// Allow specific trusted origins:
res.setHeader(
  'Content-Security-Policy',
  "frame-ancestors 'self' https://dashboard.myapp.com"
);

// Using helmet (sets both automatically):
import helmet from 'helmet';
app.use(helmet({
  frameguard: { action: 'deny' },  // Sets X-Frame-Options: DENY
  contentSecurityPolicy: {
    directives: {
      frameAncestors: ["'none'"],  // Sets CSP frame-ancestors 'none'
    },
  },
}));
